"""
eBFE Model Organization Functions

Organization functions for specific FEMA eBFE/BLE models used in example notebooks.

These functions provide tested, deterministic organization for:
- Spring Creek (12040102) - Pattern 3a: Single 2D model with nested zip
- North Galveston Bay (12040203) - Pattern 4: Compound HMS + RAS
- Upper Guadalupe (12100201) - Pattern 3b: Cascaded watershed models
- San Gabriel (12070205) - Pattern 3b: Five-project DSS fan-in delivery
- Double Mountain Fork Brazos (12050004) - Pattern 3b: Four-project 2D chain
- Eleven Point (11010011) - Pattern 3: Small 2D model archive, HEC-RAS >6.2
- Spring River (11010010) - Pattern 3: Distinct Spring HUC model archive
- Lower Colorado-Cummins (12090301) - Pattern 1D-BLE: Multiple 1D steady-state reach models
- Rio Hondo (13060008) - Pattern 1D-BLE: Multiple 1D steady-state reach models
- Lower Brazos (12070104) - Pattern 2: URL links file with very large component zips
- Amite (08070202) - Pattern 2: URL links file with separate component zips
- Tickfaw (08070203) - Pattern 3: Single large model archive
- Lake Maurepas (08070204) - Pattern 3: Single model archive
- Lower Ouachita-Bayou De Loutre (08040202) - Pattern 3: Single archive w/ nested Hydraulic Models zip
- Lower Ouachita (08040207) - Pattern 2: URL-index; loose per-plan Output HDFs (10/100/500yr published)
- Boeuf (08050001) - Pattern 2: 6-part split (~175 GiB), multi-work-area BO1..BOn, LA North
- Bayou D'Arbonne (08040206) - Pattern 2: URL-index; results bundled inside the Input zip

For organizing other eBFE models, use the organizing-ebfe-models agent skill which
handles all patterns dynamically and generates new functions as needed.

Generated by: organizing-ebfe-models agent skill
Last Updated: 2026-09-11
"""

