    @staticmethod
    @log_call
    def organize_lower_brazos(
        downloaded_folder: Optional[Path] = None,
        output_folder: Optional[Path] = None,
        download_components: bool = False,
        components: Optional[List[str]] = None,
        validate_dss: bool = False
    ) -> Path:
        """
        Organize Lower Brazos (12070104) eBFE model components.

        Lower Brazos is a Pattern 2 delivery with a small inventory and three
        very large model component zips (about 188 GB, 229 GB, and 190 GB).
        By default this function downloads only the inventory/manifest and
        creates a clear delivery shell. Pass ``download_components=True`` and
        optionally ``components=['lb_ma01']`` to download/extract model zips.

        Args:
            downloaded_folder: Local cache folder for component downloads.
                Default: ``./ebfe_downloads/12070104_LowerBrazos``.
            output_folder: Output location.
                Default: ``./ebfe_organized/LowerBrazos_12070104``.
            download_components: Download/extract the huge model components.
                Default False to avoid accidental 600+ GB downloads.
            components: Component keys to process. Valid keys are
                ``inventory``, ``lb_ma01``, ``lb_ma02``, ``lb_ma03``.
            validate_dss: Run DSS validation after organization.

        Returns:
            Path to the organized Lower Brazos delivery folder.
        """
        RasEbfeModels._ensure_console_output_safe()
        if downloaded_folder is None:
            downloaded_folder = Path("./ebfe_downloads/12070104_LowerBrazos")
        else:
            downloaded_folder = Path(downloaded_folder)

        if output_folder is None:
            output_folder = Path("./ebfe_organized/LowerBrazos_12070104")
        else:
            output_folder = Path(output_folder)

        selected = list(components or ['lb_ma01', 'lb_ma02', 'lb_ma03'])
        invalid = sorted(set(selected) - {'inventory', 'lb_ma01', 'lb_ma02', 'lb_ma03'})
        if invalid:
            raise ValueError(f"Unknown Lower Brazos component(s): {', '.join(invalid)}")

        folders = {
            'hms': output_folder / "HMS Model",
            'ras': output_folder / "RAS Model",
            'spatial': output_folder / "Spatial Data",
            'docs': output_folder / "Documentation",
            'agent': output_folder / "agent"
        }
        for folder in folders.values():
            folder.mkdir(parents=True, exist_ok=True)

        RasEbfeModels._emit("Organizing Lower Brazos (12070104) - Pattern 2")
        RasEbfeModels._emit(f"Source/cache: {downloaded_folder}")
        RasEbfeModels._emit(f"Output: {output_folder}\n")

        downloaded_folder.mkdir(parents=True, exist_ok=True)
        urls = RasEbfeModels._LOWER_BRAZOS_URLS

        RasEbfeModels._emit("[1/4] Downloading inventory/manifest...")
        inventory_path = downloaded_folder / "2D_Model_Inventory_Lower_Brazos.xlsx"
        RasEbfeModels._download_component(
            urls['inventory'],
            inventory_path,
            "Lower Brazos inventory (80 KB)"
        )
        shutil.copy2(inventory_path, folders['docs'] / inventory_path.name)

        manifest_path = downloaded_folder / "12070104_ModelURLs.txt"
        manifest_text = RasEbfeModels._build_lower_brazos_manifest_text()
        manifest_path.write_text(manifest_text, encoding='utf-8')
        shutil.copy2(manifest_path, folders['docs'] / manifest_path.name)

        processed_components = []
        if download_components:
            RasEbfeModels._emit("\n[2/4] Downloading selected model components...")
            for key in selected:
                if key == 'inventory':
                    continue
                zip_path = downloaded_folder / f"{key.upper()}.zip"
                RasEbfeModels._download_component(
                    urls[key],
                    zip_path,
                    f"Lower Brazos {key.upper()} model component"
                )
                extracted = downloaded_folder / f"{key.upper()}_extracted"
                RasEbfeModels._extract_component(zip_path, extracted, key.upper())
                processed_components.append(extracted)
        else:
            RasEbfeModels._emit("\n[2/4] Model component downloads skipped")
            RasEbfeModels._emit("  Pass download_components=True to fetch the 600+ GB model zips.")

        RasEbfeModels._emit("\n[3/4] Organizing extracted RAS models...")
        copied_files = 0
        mesh_patch_record = {
            "status": "skipped",
            "reason": "Lower Brazos components were not downloaded",
        }
        if processed_components:
            for component_root in processed_components:
                component_name = component_root.name.replace("_extracted", "")
                component_source = RasEbfeModels._select_split_delivery_source_root(
                    component_root
                )
                component_destination = folders['ras'] / component_name
                copied_files += RasEbfeModels._copy_tree_contents(
                    component_source,
                    component_destination,
                    skip_suffixes={".zip"},
                )
                RasEbfeModels._normalize_split_delivery_ras_folder(
                    component_destination
                )
                projects = RasEbfeModels._discover_valid_ras_projects(
                    component_destination
                )
                if not projects:
                    RasEbfeModels._emit(f"  No valid RAS projects found in {component_source}")
                    continue
                RasEbfeModels._emit(
                    "  Staged "
                    f"{component_name} from {component_source.name}: "
                    f"{len(projects)} RAS project folder(s)"
                )

            standardization = RasEbfeModels._standardize_ras_model_tree(folders['ras'])
            mesh_patch_record = RasEbfeModels._apply_lower_brazos_ma03_mesh_seed_patch(
                folders['ras']
            )
            if mesh_patch_record.get("status") == "applied":
                RasEbfeModels._emit(
                    "  Applied Lower Brazos MA03 mesh seed patch "
                    f"(+{mesh_patch_record.get('points_added', 0)} points)"
                )
            elif mesh_patch_record.get("status") == "already_applied":
                RasEbfeModels._emit("  Lower Brazos MA03 mesh seed patch already present")
            if validate_dss:
                RasEbfeModels._validate_dss_files(folders['ras'])
        else:
            readme = folders['ras'] / "README_DOWNLOAD_REQUIRED.md"
            readme.write_text(
                "# Lower Brazos RAS Components Not Downloaded\n\n"
                "This delivery shell contains the eBFE inventory and URL manifest.\n"
                "The RAS model components are very large. Re-run "
                "`RasEbfeModels.organize_lower_brazos(download_components=True)` "
                "with selected components when sufficient disk and time are "
                "available.\n",
                encoding='utf-8'
            )
            standardization = {'project_count': 0, 'projects': []}

        RasEbfeModels._emit("\n[4/4] Creating metadata...")
        (folders['hms'] / "README.md").write_text(
            "# HMS Model Not Organized Yet\n\n"
            "Lower Brazos model component downloads were organized from the eBFE "
            "RAS model URL manifest. HMS content is not part of the current "
            "RAS component organizer.\n",
            encoding='utf-8'
        )
        RasEbfeModels._create_lower_brazos_log(
            folders['agent'],
            downloaded_folder,
            output_folder,
            download_components,
            selected,
            processed_components,
            copied_files,
            standardization,
            mesh_patch_record,
        )

        RasEbfeModels._emit(f"\nLower Brazos organized to: {output_folder}")
        return output_folder

    @staticmethod
    def _parse_storage_area_seed_points(
        geom_text_path: Path,
        mesh_name: str,
    ):
        """Read a HEC-RAS ``Storage Area 2D Points`` block as a NumPy array."""
        import numpy as np

        lines = geom_text_path.read_text(
            encoding="utf-8",
            errors="replace",
        ).splitlines()
        current_area = None
        idx = 0
        while idx < len(lines):
            line = lines[idx]
            if line.startswith("Storage Area="):
                current_area = line.split("=", 1)[1].split(",", 1)[0].strip()
            elif (
                line.startswith("Storage Area 2D Points=")
                and current_area == mesh_name
            ):
                try:
                    point_count = int(line.split("=", 1)[1].strip())
                except ValueError as exc:
                    raise ValueError(
                        f"Invalid Storage Area 2D Points count in {geom_text_path}: {line}"
                    ) from exc

                values: list[float] = []
                idx += 1
                while idx < len(lines) and len(values) < point_count * 2:
                    coord_line = lines[idx]
                    chunks = [
                        coord_line[start : start + 16]
                        for start in range(0, len(coord_line), 16)
                    ]
                    parsed_this_line = 0
                    for chunk in chunks:
                        token = chunk.strip()
                        if not token:
                            continue
                        try:
                            values.append(float(token))
                            parsed_this_line += 1
                        except ValueError:
                            continue
                    if parsed_this_line == 0:
                        for token in coord_line.split():
                            try:
                                values.append(float(token))
                            except ValueError:
                                continue
                    idx += 1

                if len(values) < point_count * 2:
                    raise ValueError(
                        f"Only parsed {len(values) // 2} of {point_count} "
                        f"Storage Area 2D Points from {geom_text_path}"
                    )
                return np.array(values[: point_count * 2], dtype=float).reshape(
                    point_count,
                    2,
                )
            idx += 1

        raise ValueError(
            f"Storage Area 2D Points block for {mesh_name!r} not found in "
            f"{geom_text_path}"
        )

    @staticmethod
    def _apply_lower_brazos_ma03_mesh_seed_patch(ras_root: Path) -> Dict[str, Any]:
        """
        Apply the validated four-seed MA03 mesh repair needed for preprocessing.

        The delivered MA03 text geometry can produce one breakline-only
        ``MaxFacesPerCellExceeded`` cell during command-line preprocessing.
        These four seed points were derived from RasMapperLib bad-index cells
        592314/592315 and validated with HEC-RAS 6.6 geometry preprocessing.
        """
        import numpy as np
        from ras_commander.geom.GeomMesh import (
            _patch_text_seeds,
            _set_point_generation_data,
        )

        ras_root = Path(ras_root)
        project_folder = ras_root / "LB_MA03"
        geom_text_path = project_folder / "MA_3.g02"
        mesh_name = "MA_3_2DArea"

        record: Dict[str, Any] = {
            "project": "LB_MA03",
            "geometry": str(geom_text_path),
            "mesh_name": mesh_name,
            "status": "skipped",
        }

        if not geom_text_path.exists():
            record["reason"] = "MA_3.g02 not found"
            return record

        existing_points = RasEbfeModels._parse_storage_area_seed_points(
            geom_text_path,
            mesh_name,
        )
        patch_points = np.array(
            RasEbfeModels._LOWER_BRAZOS_MA03_MESH_PATCH_POINTS,
            dtype=float,
        )

        missing_points = []
        for point in patch_points:
            matches = np.isclose(
                existing_points,
                point,
                atol=1e-6,
                rtol=0.0,
            )
            if not np.any(np.all(matches, axis=1)):
                missing_points.append(point)

        record["old_seed_count"] = int(len(existing_points))
        if not missing_points:
            record["status"] = "already_applied"
            record["new_seed_count"] = int(len(existing_points))
            record["points_added"] = 0
            return record

        points_to_add = np.array(missing_points, dtype=float)
        combined_points = np.vstack([existing_points, points_to_add])
        _set_point_generation_data(geom_text_path, 200.0, mesh_name=mesh_name)
        _patch_text_seeds(geom_text_path, combined_points, mesh_name=mesh_name)

        record.update(
            {
                "status": "applied",
                "new_seed_count": int(len(combined_points)),
                "points_added": int(len(points_to_add)),
                "added_points": points_to_add.tolist(),
                "reason": (
                    "Validated MA03 repair for one breakline-only "
                    "MaxFacesPerCellExceeded mesh cell."
                ),
            }
        )
        return record

